// Act Natural!: the situations and their conversations, one per level (A1, A2, B1, B2).
//
// One line per turn:  T(what the other person says, the task, good answers, key words, wrong answer 1, wrong answer 2, flags)
//   good answers   "answer 1|answer 2"                  the first one is the model answer
//   key words      "can i have/i'd like ; coffee"       every group (between ;) must be in the answer, any word of a group (between /) is fine
//   wrong answers  "wrong sentence :: why it's wrong"   used in "Choose" mode and to explain the mistake
//   flags          "p" = a request: without please / could / would the other person gets annoyed
//                  "q" = the student must ASK a question
// After the last turn, the other person says "end".

function T(npc, task, say, need, w1, w2, flags = ""){
  const wrong = [w1, w2].map(w => { const [t, why] = w.split(" :: "); return { t: t.trim(), why: (why || "").trim() }; });
  return { npc, task, say: say.split("|").map(s => s.trim()), need: need.split(";").map(g => g.split("/").map(a => a.trim().toLowerCase()).filter(Boolean)), wrong, polite: flags.includes("p"), question: flags.includes("q") };
}

